{"command":"cd /testbed && python3 - <<'EOF'
import sqlite3, csv, json
from crm_ops.importer import compute_record_hash

con = sqlite3.connect("/var/lib/acme/crm.sqlite")
con.row_factory = sqlite3.Row
baseline = json.load(open("/tmp/baseline.json"))

with open("/tmp/partner_pkg/partner_export.csv", newline="") as f:
    csv_rows = {r["customer_id"]: r for r in csv.DictReader(f)}

errors = []

def row(cid, table):
    return dict(con.execute(f"SELECT * FROM {table} WHERE customer_id=?", (cid,)).fetchone())

active = [r["customer_id"] for r in con.execute("SELECT customer_id FROM customers WHERE status='active' ORDER BY customer_id")]
paused = [r["customer_id"] for r in con.execute("SELECT customer_id FROM customers WHERE status='paused' ORDER BY customer_id")]
assert len(active) == 150 and len(paused) == 30

n_listed = n_absent = 0
for cid in active:
    c, o, k = row(cid, "customers"), row(cid, "owner_mappings"), row(cid, "consent_records")
    b = baseline["active"][cid]
    # preserved fields
    for f in ("legal_name", "status", "external_anchor", "anchor_segment"):
        if c[f] != b["customer"][f]: errors.append(f"{cid}: {f} changed {b['customer'][f]} -> {c[f]}")
    # owner/territory unassigned
    if o["account_owner"] != "unassigned" or o["territory"] != "unassigned":
        errors.append(f"{cid}: owner not unassigned {o}")
    # consent
    if k["consent_status"] != "revoked" or k["source"] != "partner_sync" or k["updated_at"] != "2026-06-26T16:40:00Z":
        errors.append(f"{cid}: consent wrong {k}")
    if k["consent_version"] != b["consent"]["consent_version"]:
        errors.append(f"{cid}: consent_version not retained")
    if cid in csv_rows:
        n_listed += 1
        r = csv_rows[cid]
        if (c["contact_name"], c["contact_email"], c["industry"]) != (r["contact_name"], r["contact_email"], r["industry"]):
            errors.append(f"{cid}: listed contact/industry mismatch")
        if c["subscription_status"] != "snapshot_unspecified":
            errors.append(f"{cid}: subscription_status={c['subscription_status']}")
    else:
        n_absent += 1
        if c["contact_name"] != "" or c["contact_email"] != "":
            errors.append(f"{cid}: absent contact not empty")
        if c["industry"] != "unknown" or c["subscription_status"] != "removed_from_partner_snapshot":
            errors.append(f"{cid}: absent industry/sub wrong")
    # hash recompute with the tool's own function
    expected = compute_record_hash(c, o, k)
    if c["record_hash"] != expected:
        errors.append(f"{cid}: record_hash {c['record_hash']} != recomputed {expected}")

# paused untouched
for cid in paused:
    for table, key in (("customers", "customer"), ("owner_mappings", "owner"), ("consent_records", "consent")):
        cur = row(cid, table)
        base = {k2: v2 for k2, v2 in baseline["paused"][cid][key].items()}
        if cur != base:
            errors.append(f"paused {cid} {table} changed: {cur} != {base}")

# audit event
ev = con.execute("SELECT event_type, scope, details FROM audit_events ORDER BY id DESC LIMIT 1").fetchone()
print("latest audit event:", ev["event_type"], ev["scope"], ev["details"])

print(f"listed={n_listed}, absent={n_absent}, errors={len(errors)}")
for e in errors[:10]:
    print("ERROR:", e)
print("VERIFICATION", "FAILED" if errors else "PASSED")
EOF"}

